BEGIN;
INSERT INTO tipos_consulta(codigo,nombre,politica) VALUES('baja_avisos','No recibir recordatorios','bot_responde') ON CONFLICT(codigo) DO NOTHING;
ALTER TABLE contactos_whatsapp ADD COLUMN IF NOT EXISTS acepta_avisos boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS gestion_config(id smallint PRIMARY KEY CHECK(id=1), automaticos boolean NOT NULL DEFAULT false);
INSERT INTO gestion_config VALUES(1,false) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS gestion_notas(id bigserial PRIMARY KEY, cliente_id bigint NOT NULL REFERENCES clientes(id), autor_id bigint NOT NULL REFERENCES funcionarios(id), texto text NOT NULL CHECK(length(trim(texto)) BETWEEN 3 AND 2000), creada_en timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gestion_tareas(id bigserial PRIMARY KEY, titulo text NOT NULL CHECK(length(trim(titulo)) BETWEEN 3 AND 200), detalle text NOT NULL DEFAULT '', cliente_id bigint REFERENCES clientes(id), interesado_id bigint REFERENCES interesados(id), asignada_a_id bigint NOT NULL REFERENCES funcionarios(id), creada_por_id bigint NOT NULL REFERENCES funcionarios(id), vence date NOT NULL, estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','hecha','cancelada')), creada_en timestamptz NOT NULL DEFAULT now(), completada_en timestamptz, CHECK((estado='hecha')=(completada_en IS NOT NULL)));
CREATE INDEX IF NOT EXISTS gestion_tareas_abiertas ON gestion_tareas(asignada_a_id,vence) WHERE estado='pendiente';
CREATE TABLE IF NOT EXISTS gestion_avisos(id bigserial PRIMARY KEY, clave text NOT NULL UNIQUE, tipo text NOT NULL CHECK(tipo IN ('renovacion','cuota','seguimiento')), contacto_id bigint NOT NULL REFERENCES contactos_whatsapp(id), poliza_id bigint REFERENCES polizas(id), cuota_id bigint REFERENCES cuotas(id), interesado_id bigint REFERENCES interesados(id), estado text NOT NULL DEFAULT 'pendiente' CHECK(estado IN ('pendiente','preparado','manual','cancelado')), mensaje_id bigint UNIQUE REFERENCES mensajes(id), resuelto_por_id bigint REFERENCES funcionarios(id), creado_en timestamptz NOT NULL DEFAULT now(), resuelto_en timestamptz, CHECK(estado<>'manual' OR (resuelto_por_id IS NOT NULL AND resuelto_en IS NOT NULL)));
COMMIT;
